def fits_poly(P,O,n,maxdeg=2):
    terms=[(0,0),(1,0),(0,1),(1,1),(2,0),(0,2)]
    sols=[]
    # separable coefficient vectors 3^6=729 each =>531k combos too many; build matching possible f,g values by constraints brute
    for cf in itertools.product(range(n),repeat=len(terms)):
      for cg in itertools.product(range(n),repeat=len(terms)):
       ok=True
       for r in range(len(O)):
        for c in range(len(O[0])):
         vals=[1,r,c,r*c,r*r,c*c]
         f=sum(a*v for a,v in zip(cf,vals))%n; g=sum(a*v for a,v in zip(cg,vals))%n
         if P[f][g]!=O[r][c]:ok=False;break
        if not ok:break
       if ok: sols.append((cf,cg))
    return sols
